#[cfg(test)]
fn observe_claude_process_spawned(pid: Option<u32>) {
    let Some(pid) = pid else {
        return;
    };
    if let Some(observer) = CLAUDE_PROCESS_SPAWN_OBSERVER
        .lock()
        .expect("Claude process spawn observer mutex poisoned")
        .take()
    {
        let _ = observer.send(pid);
    }
}

