/// How the Claude backend disposed of a send: either it fully handled the
/// input (turn started, tool response answered, or a visible error emitted),
/// or it was busy with an already-active turn and did not consume the
/// message — the caller must requeue it.
enum ClaudeSendAdmission {
    Handled,
    Busy,
}

#[derive(Clone)]
struct PendingAskUserQuestionControl {
    request_id: String,
    tool_call_id: String,
    tool_name: String,
    input: Value,
}

#[derive(Clone)]
struct PendingExitPlanModeControl {
    request_id: String,
    tool_call_id: String,
    tool_name: String,
    input: Value,
    plan: Option<String>,
    plan_path: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClaudeEffort {
    Low,
    Medium,
    High,
    XHigh,
    Max,
}

impl ClaudeEffort {
    const ALL: [Self; 5] = [Self::Low, Self::Medium, Self::High, Self::XHigh, Self::Max];

    fn as_str(self) -> &'static str {
        match self {
            Self::Low => "low",
            Self::Medium => "medium",
            Self::High => "high",
            Self::XHigh => "xhigh",
            Self::Max => "max",
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Low => "Low",
            Self::Medium => "Medium",
            Self::High => "High",
            Self::XHigh => "XHigh",
            Self::Max => "Max",
        }
    }

    fn parse(value: &str) -> Result<Self, String> {
        match value.trim().to_ascii_lowercase().as_str() {
            "low" => Ok(Self::Low),
            "medium" => Ok(Self::Medium),
            "high" => Ok(Self::High),
            "xhigh" => Ok(Self::XHigh),
            "max" => Ok(Self::Max),
            value => Err(format!(
                "unsupported Claude effort '{value}'; expected one of: {}",
                Self::ALL
                    .iter()
                    .map(|effort| effort.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            )),
        }
    }
}

